44	        jdbc.execute("TRUNCATE TABLE project RESTART IDENTITY");
45	        jdbc.execute("TRUNCATE TABLE contact RESTART IDENTITY");
46	        jdbc.execute("TRUNCATE TABLE client RESTART IDENTITY");
47	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
48	    }
