51	    @PostMapping("/seed")
52	    @SuppressWarnings("unchecked")
53	    public void seed(@RequestBody Map<String, Object> fixture) {
54	        List<Map<String, Object>> clients =
55	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
56	        for (Map<String, Object> client : clients) {
57	            jdbc.update("INSERT INTO client (id, name, email) VALUES (?, ?, ?)",
58	                    ((Number) client.get("id")).longValue(), client.get("name"), client.get("email"));
59	        }
60	        List<Map<String, Object>> projects =
61	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
62	        for (Map<String, Object> project : projects) {
63	            jdbc.update("INSERT INTO project (id, name, client_id) VALUES (?, ?, ?)",
64	                    ((Number) project.get("id")).longValue(), project.get("name"),
65	                    ((Number) project.get("clientId")).longValue());
66	        }
67	        List<Map<String, Object>> tasks =
68	                (List<Map<String, Object>>) fixture.getOrDefault("tasks", List.of());
69	        for (Map<String, Object> task : tasks) {
70	            Object done = task.getOrDefault("done", Boolean.FALSE);
71	            jdbc.update("INSERT INTO task (id, project_id, title, done) VALUES (?, ?, ?, ?)",
72	                    ((Number) task.get("id")).longValue(),
73	                    ((Number) task.get("projectId")).longValue(), task.get("title"),
74	                    Boolean.TRUE.equals(done));
75	        }
76	        List<Map<String, Object>> notes =
77	                (List<Map<String, Object>>) fixture.getOrDefault("notes", List.of());
78	        long maxNoteId = 0;
79	        for (Map<String, Object> note : notes) {
80	            long noteId = ((Number) note.get("id")).longValue();
81	            maxNoteId = Math.max(maxNoteId, noteId);
82	            jdbc.update(
83	                    "INSERT INTO note (id, target_type, target_id, body, at) VALUES (?, ?, ?, ?, ?)",
84	                    noteId, note.get("targetType"),
85	                    ((Number) note.get("targetId")).longValue(), note.get("text"),
86	                    java.sql.Timestamp.from(java.time.Instant.parse(note.get("at").toString())));
87	        }
88	        if (maxNoteId > 0) {
89	            // Seeding explicit ids does not advance H2's IDENTITY sequence, so a note created later
90	            // through the API would collide on id=1. Nudge the sequence past the seeded ids.
91	            jdbc.execute("ALTER TABLE note ALTER COLUMN id RESTART WITH " + (maxNoteId + 1));
92	        }
93	        List<Map<String, Object>> tags =
94	                (List<Map<String, Object>>) fixture.getOrDefault("tags", List.of());
95	        for (Map<String, Object> tag : tags) {
96	            jdbc.update("INSERT INTO tag (id, name) VALUES (?, ?)",
97	                    ((Number) tag.get("id")).longValue(), tag.get("name"));
98	        }
99	        List<Map<String, Object>> projectTags =
100	                (List<Map<String, Object>>) fixture.getOrDefault("projectTags", List.of());
101	        for (Map<String, Object> projectTag : projectTags) {
102	            jdbc.update("INSERT INTO project_tag (project_id, tag_id) VALUES (?, ?)",
103	                    ((Number) projectTag.get("projectId")).longValue(),
104	                    ((Number) projectTag.get("tagId")).longValue());
105	        }
106	        List<Map<String, Object>> contacts =
107	                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
108	        for (Map<String, Object> contact : contacts) {
109	            jdbc.update(
110	                    "INSERT INTO contact (id, client_id, name, email, role) VALUES (?, ?, ?, ?, ?)",
111	                    ((Number) contact.get("id")).longValue(),
112	                    ((Number) contact.get("clientId")).longValue(), contact.get("name"),
113	                    contact.get("email"), contact.get("role"));
114	        }
115	        List<Map<String, Object>> invoices =
116	                (List<Map<String, Object>>) fixture.getOrDefault("invoices", List.of());
117	        for (Map<String, Object> invoice : invoices) {
118	            Object status = invoice.getOrDefault("status", "DRAFT");
119	            Object issuedDate = invoice.get("issuedDate");
120	            Object dueDate = invoice.get("dueDate");
